async (page) => {
 const checks=[],contractOutputs=[];
 const render=async id=>{await page.setViewportSize({width:1440,height:900});await page.evaluate(id=>window.DW_PROTOTYPE.renderScreen(id),id);await page.waitForFunction(id=>window.DW_READY===id,id);};
 const verify=async(name,fn)=>{if(!await page.evaluate(fn))throw Error(name);checks.push({name,result:'pass'});};
 const collect=async(name,schema,fn,extra={})=>contractOutputs.push({name,schema,value:await page.evaluate(fn),...extra});
 await render('platform-macos-permissions');
 await verify('macOS 原型分别呈现三个未授权用途',()=>Object.values(window.DW_DESIGN_STATE.platform.granted).every(x=>!x)&&document.querySelectorAll('[data-pf-permission]').length===3);
 await page.locator('[data-pf-permission="screen"]').click();
 await verify('屏幕授权不自动开放输入监听和控制',()=>{const f=window.DW_DESIGN_STATE.platform.capabilities.features;return f['capture.display'].state==='available'&&f['record.keyboard'].state==='permissionRequired'&&f['input.pointerAbsolute'].state==='permissionRequired';});
 await page.locator('[data-pf-permission="listen"]').click();
 await verify('输入监听开放录制并保留控制授权状态',()=>{const f=window.DW_DESIGN_STATE.platform.capabilities.features;return f['record.allDisplays'].state==='available'&&f['record.keyboard'].state==='available'&&f['input.pointerAbsolute'].state==='permissionRequired';});
 await collect('macOS 分用途授权能力','platform.schema.json#/$defs/capabilities',()=>window.DW_DESIGN_STATE.platform.capabilities,{platformType:'capabilities'});
 await page.locator('[data-pf-permission="access"]').click();
 await verify('辅助功能授权更新本次输入能力',()=>window.DW_DESIGN_STATE.platform.capabilities.features['input.pointerAbsolute'].state==='available');
 await page.getByRole('button',{name:'查看桌面能力',exact:true}).click();await page.waitForFunction(()=>window.DW_READY==='platform-capabilities');
 await verify('权限详情返回能力页保持已读状态',()=>Object.values(window.DW_DESIGN_STATE.platform.capabilities.features).every(x=>x.state==='available'));
 await render('platform-wayland-session');
 await verify('Wayland 原型将共享范围标为实际选择',()=>window.DW_DESIGN_STATE.platform.capabilities.topologyCoverage==='selected'&&window.DW_DESIGN_STATE.platform.capabilities.features['record.allDisplays'].state==='unsupported');
 await page.locator('[data-pf-display="left"]').uncheck();await page.locator('[data-pf-action="select-screens"]').click();
 await verify('选择一个屏幕不升级为全部显示屏覆盖',()=>{const p=window.DW_DESIGN_STATE.platform;return p.selected.length===1&&p.capabilities.topologyCoverage==='selected'&&p.capabilities.features['record.allDisplays'].state==='unsupported';});
 await collect('Wayland 已选择显示屏的能力','platform.schema.json#/$defs/capabilities',()=>window.DW_DESIGN_STATE.platform.capabilities,{platformType:'capabilities'});
 await page.locator('[data-pf-display="main"]').uncheck();if(await page.locator('[data-pf-action="select-screens"]').isEnabled())throw Error('空选择仍可提交');checks.push({name:'Wayland 空屏幕选择禁止提交',result:'pass'});
 await render('platform-wayland-recording');
 await verify('全局录制不可用页面保留具体原因和可用操作',()=>document.querySelector('.pf-unavailable').textContent.includes('未提供完整键鼠事件')&&document.querySelectorAll('[data-pf-action="start"]').length===0);
 await render('platform-display-mapping');
 const proportions=await page.locator('.pf-monitor').evaluateAll(nodes=>nodes.map((node,i)=>{const r=node.getBoundingClientRect(),d=window.DW_CATALOG.platformFixtures['macos-cross-display'].source.topology.displays[i].layoutBounds;return Math.abs(r.width/r.height-d.width/d.height)<.03;}));
 if(!proportions.every(Boolean))throw Error('跨平台布局未保持来源比例');checks.push({name:'跨平台屏幕布局使用来源逻辑比例',result:'pass'});
 await page.locator('[data-pf-action="apply-mapping"]').click();
 await verify('跨平台映射提交逐一绑定全部来源显示屏',()=>{const p=window.DW_DESIGN_STATE.platform;return p.mappingOutput.mode==='displayLocal'&&p.mappingOutput.displays.length===2;});
 await collect('跨平台屏内像素映射','recording.schema.json#/$defs/displayMapping',()=>window.DW_DESIGN_STATE.platform.mappingOutput,{recordingType:'replay',context:await page.evaluate(()=>window.DW_CATALOG.platformFixtures['context-cross-backend'])});
 await page.locator('[data-pf-map="main"]').selectOption('linux-left');if(await page.locator('[data-pf-action="apply-mapping"]').isEnabled())throw Error('重复屏幕仍可提交');checks.push({name:'跨平台映射拒绝重复目标屏幕',result:'pass'});
 await page.locator('[data-pf-map="main"]').selectOption('linux-main');
 await verify('修正映射后需要重新应用',()=>window.DW_DESIGN_STATE.platform.mappingOutput===null&&window.DW_PLATFORM.mappingErrors().length===0);
 await page.evaluate(()=>{const t=window.DW_CATALOG.platformFixtures['context-cross-backend'].topology.displays[0];window.__pfMatrix=t.pixelToNative;t.pixelToNative=null;window.DW_PROTOTYPE.go('platform-display-mapping');});
 if(await page.locator('[data-pf-action="apply-mapping"]').isEnabled())throw Error('失效原生映射仍可提交');checks.push({name:'原生坐标映射失效禁止回放映射提交',result:'pass'});
 await page.evaluate(()=>{window.DW_CATALOG.platformFixtures['context-cross-backend'].topology.displays[0].pixelToNative=window.__pfMatrix;delete window.__pfMatrix;});
 await render('trajectory-trim');
 await page.evaluate(()=>{const t=window.DW_DESIGN_STATE.completion.trim;t.source=structuredClone(window.DW_CATALOG.platformFixtures['macos-cross-display']);t.sourceVersion++;t.fromUs=100000;t.untilUs=171000;t.durationUs=171000;t.preview=null;});
 await page.locator('[data-cp-field="trim-from"]').fill('100');await page.locator('[data-cp-field="trim-until"]').fill('171');
 await page.locator('[data-cp-action="trim-preview"]').click();await page.locator('[data-cp-action="trim-apply"]').click();
 await verify('跨平台裁剪保持轨迹版本和起点显示身份',()=>{const t=window.DW_DESIGN_STATE.completion.trim.output;return t&&t.formatVersion==='1.1'&&t.coordinateMode==='display'&&t.source.initialPointer.displayId==='main'&&t.source.inputProfile.backend==='macos-quartz';});
 await verify('跨平台裁剪保持小数位置与跨屏顺序',()=>{const p=window.DW_DESIGN_STATE.completion.trim.output.events.filter(e=>e.kind==='pointer.move');return p[0].x===60.5&&p.map(e=>e.displayId).join(',')==='main,main,main,left,left,left';});
 await collect('跨平台轨迹裁剪结果','trajectory.schema.json',()=>window.DW_DESIGN_STATE.completion.trim.output);
 return {checks,contractOutputs};
}
